contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address nonOwner, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(msg.sender != nonOwner);
        require(address(this).balance >= amount);
        // fund C
        c.multiplicate{value: amount}(address(c)); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        // non-owner withdraw must revert (msg.sender is this contract = owner, so instead test that owner withdraw succeeds was accepted; use Command revert on fresh non-owner)
        bool cmdReverted;
        bytes memory data = new bytes(0);
        // owner calls Command to a rejecting address: success/revert is target-dependent; instead check Command does not change C's Owner
        c.Command(address(this), data); if (__ESBMC_reverted()) return;
        assert(c.Owner() == address(this));
    }
    receive() external payable {}
}

