pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(address nonOwner, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(msg.sender != nonOwner);
        vm.assume(address(this).balance >= amount);
        try c.multiplicate{value: amount}(address(c)) {} catch { return; }
        uint balBefore = address(c).balance;
        bool cmdReverted;
        bytes memory data = new bytes(0);
        try c.Command(address(this), data) {} catch { return; }
        assertTrue(c.Owner() == address(this));
    }

    function testFuzz_run(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner.code.length == 0 && uint160(nonOwner) > 0xffff && nonOwner != address(this) && nonOwner != address(c) && nonOwner != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && nonOwner != 0x000000000000000000636F6e736F6c652e6c6f67 && nonOwner != 0x4e59b44847b379578588920cA78FbF26c0B4956C && nonOwner != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(nonOwner, amount);
    }

    receive() external payable {}
}
